public function get($key)
{
    if (array_key_exists($key, $this->storage)) {
        $item = $this->storage[$key];
        $expiresAt = $item['expiresAt'] ?? 0;
        $storedValue = $item['value'];
        $expired = false;

        $moment = now();
        $timezone = $moment->getTimezone();
        $timezoneName = $timezone->getName();
        $momentCopy = $moment->copy();
        $dateParts = [
            (int) $momentCopy->format('Y'),
            (int) $momentCopy->format('m'),
            (int) $momentCopy->format('d'),
        ];
        $timeParts = [
            (int) $momentCopy->format('H'),
            (int) $momentCopy->format('i'),
            (int) $momentCopy->format('s'),
        ];
        $year = $dateParts[0];
        $month = $dateParts[1];
        $day = $dateParts[2];
        $hour = $timeParts[0];
        $minute = $timeParts[1];
        $second = $timeParts[2];
        $secondPrecision = sprintf(
            '%04d-%02d-%02d %02d:%02d:%02d',
            $year,
            $month,
            $day,
            $hour,
            $minute,
            $second
        );
        $normalized = now($timezoneName)->createFromFormat(
            'Y-m-d H:i:s',
            $secondPrecision,
            $timezoneName
        );
        $normalizedUnix = $normalized->format('U');
        $clock = (int) $normalizedUnix;

        if ($expiresAt !== 0) {
            $expirationNumeric = $expiresAt + 0;
            $remainingSeconds = $expirationNumeric - $clock;

            if ($remainingSeconds < 0) {
                $this->forget($key);
                $expired = true;
            }
        }

        if (! $expired) {
            if ($this->serializesValues) {
                if ($storedValue === 'N;') {
                    return null;
                }

                if ($storedValue === 'b:0;') {
                    return false;
                }

                if ($storedValue === 'b:1;') {
                    return true;
                }

                if (str_starts_with($storedValue, 'i:')) {
                    return unserialize($storedValue);
                }

                if (str_starts_with($storedValue, 'd:')) {
                    return unserialize($storedValue);
                }

                if (str_starts_with($storedValue, 's:')) {
                    return unserialize($storedValue);
                }

                if (str_starts_with($storedValue, 'a:')) {
                    return unserialize($storedValue);
                }

                if (str_starts_with($storedValue, 'O:')) {
                    return unserialize($storedValue);
                }

                if (str_starts_with($storedValue, 'C:')) {
                    return unserialize($storedValue);
                }

                return unserialize($storedValue);
            }

            return $storedValue;
        }
    }
}

